CREATE TABLE tenants(id text PRIMARY KEY,name text NOT NULL,status text NOT NULL DEFAULT 'active' CHECK(status IN('active','suspended')),timezone text NOT NULL DEFAULT 'Asia/Jakarta');
CREATE TABLE users(id text PRIMARY KEY,tenant_id text NOT NULL REFERENCES tenants(id),username text NOT NULL,password_hash text NOT NULL,capabilities jsonb NOT NULL DEFAULT '[]',brand_ids jsonb NOT NULL DEFAULT '[]',all_brands boolean NOT NULL DEFAULT false,status text NOT NULL DEFAULT 'active',UNIQUE(tenant_id,username),UNIQUE(tenant_id,id));
CREATE TABLE sessions(token_hash text PRIMARY KEY,user_id text NOT NULL REFERENCES users(id),expires_at timestamptz NOT NULL);
CREATE TABLE catalog_items(id text NOT NULL,tenant_id text NOT NULL REFERENCES tenants(id),domain text NOT NULL CHECK(domain IN('product','deconstruct','brand','visual_identity','preset','binding','dependency')),brand_id text,name text NOT NULL,payload jsonb NOT NULL DEFAULT '{}',revision integer NOT NULL DEFAULT 1,archived boolean NOT NULL DEFAULT false,origin_key text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,id),UNIQUE(tenant_id,origin_key));
CREATE TABLE routines(id text NOT NULL,tenant_id text NOT NULL REFERENCES tenants(id),brand_id text NOT NULL,draft jsonb NOT NULL,revision integer NOT NULL DEFAULT 1,active_revision integer,active_config jsonb,state text NOT NULL DEFAULT 'draft',next_run_at timestamptz,PRIMARY KEY(tenant_id,id),FOREIGN KEY(tenant_id,brand_id) REFERENCES catalog_items(tenant_id,id));
CREATE TABLE automation_runs(id text PRIMARY KEY,tenant_id text NOT NULL,routine_id text NOT NULL,scheduled_slot timestamptz,execution_mode text NOT NULL,config jsonb NOT NULL,status text NOT NULL DEFAULT 'queued',lease_owner text,lease_expires_at timestamptz,fencing_token bigint NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(tenant_id,routine_id) REFERENCES routines(tenant_id,id),UNIQUE(tenant_id,id));
CREATE UNIQUE INDEX run_slot_uq ON automation_runs(tenant_id,routine_id,scheduled_slot) WHERE execution_mode='scheduled';
CREATE TABLE content_items(id text NOT NULL,tenant_id text NOT NULL,run_id text NOT NULL,brand_id text NOT NULL,revision integer NOT NULL DEFAULT 1,status text NOT NULL DEFAULT 'queued',production_package jsonb,artifacts jsonb NOT NULL DEFAULT '{}',caption text NOT NULL DEFAULT '',PRIMARY KEY(tenant_id,id),FOREIGN KEY(tenant_id,run_id) REFERENCES automation_runs(tenant_id,id));
CREATE TABLE approvals(tenant_id text NOT NULL,item_id text NOT NULL,revision integer NOT NULL,actor_id text NOT NULL,approved_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,item_id,revision),FOREIGN KEY(tenant_id,item_id) REFERENCES content_items(tenant_id,id),FOREIGN KEY(tenant_id,actor_id) REFERENCES users(tenant_id,id));
CREATE TABLE publishing_intents(id text PRIMARY KEY,tenant_id text NOT NULL,item_id text NOT NULL,revision integer NOT NULL,account_id text NOT NULL,scheduled_at timestamptz NOT NULL,status text NOT NULL DEFAULT 'draft',provider_id text,UNIQUE(tenant_id,item_id,revision,account_id,scheduled_at),FOREIGN KEY(tenant_id,item_id,revision) REFERENCES approvals(tenant_id,item_id,revision));
CREATE TABLE stage_executions(tenant_id text NOT NULL,item_id text NOT NULL,revision integer NOT NULL,stage text NOT NULL,status text NOT NULL DEFAULT 'queued',lease_owner text,lease_expires_at timestamptz,fencing_token bigint NOT NULL DEFAULT 0,provider_job_id text,output jsonb,PRIMARY KEY(tenant_id,item_id,revision,stage),FOREIGN KEY(tenant_id,item_id) REFERENCES content_items(tenant_id,id));
CREATE TABLE pipeline_incidents(id text PRIMARY KEY,tenant_id text NOT NULL,brand_id text,run_id text,item_id text,revision integer,stage text NOT NULL,cause_group text NOT NULL,status text NOT NULL,event jsonb NOT NULL,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE notification_outbox(id text PRIMARY KEY,tenant_id text NOT NULL,event_key text NOT NULL,payload jsonb NOT NULL,status text NOT NULL DEFAULT 'queued',attempts integer NOT NULL DEFAULT 0,next_attempt_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,event_key));
CREATE TABLE audit_events(id bigserial PRIMARY KEY,tenant_id text NOT NULL,brand_id text,actor_id text,event_type text NOT NULL,event jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE import_batches(id text PRIMARY KEY,tenant_id text NOT NULL,source_system text NOT NULL,source_tenant_id text NOT NULL,manifest jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE import_origins(tenant_id text NOT NULL,source_system text NOT NULL,source_tenant_id text NOT NULL,domain text NOT NULL,source_id text NOT NULL,target_id text NOT NULL,source_hash text NOT NULL,destination_revision integer NOT NULL,batch_id text NOT NULL REFERENCES import_batches(id),PRIMARY KEY(tenant_id,source_system,source_tenant_id,domain,source_id),FOREIGN KEY(tenant_id,target_id) REFERENCES catalog_items(tenant_id,id));
